  const rc = new Array(D.r.length);
  function ring(idx) {
    let r = rc[idx];
    if (r) return r;
    const s = D.r[idx];
    r = [];
    let i = 0, n = s.length, x = 0, y = 0;
    while (i < n) {
      let b, sh = 0, v = 0;
      do { b = R[s.charCodeAt(i++)]; v |= (b & 31) << sh; sh += 5; } while (b >= 32);
      x += (v & 1) ? ~(v >>> 1) : (v >>> 1);
      sh = 0; v = 0;
      do { b = R[s.charCodeAt(i++)]; v |= (b & 31) << sh; sh += 5; } while (b >= 32);
      y += (v & 1) ? ~(v >>> 1) : (v >>> 1);
      r.push([x / 100, y / 100]);
    }
    return (rc[idx] = r);
  }
